/* From Uiverse.io by fanishah - Tags: input */
.__UIV_SCOPE__ .search-bar {
  display: flex;
}

.__UIV_SCOPE__ .search-bar input,
.__UIV_SCOPE__ .search-btn,
.__UIV_SCOPE__ .search-btn:before,
.__UIV_SCOPE__ .search-btn:after {
  transition: all 0.25s ease-out;
}

.__UIV_SCOPE__ .search-bar input,
.__UIV_SCOPE__ .search-btn {
  width: 3em;
  height: 3em;
}

.__UIV_SCOPE__ .search-bar input:invalid:not(:focus),
.__UIV_SCOPE__ .search-btn {
  cursor: pointer;
}

.__UIV_SCOPE__ .search-bar,
.__UIV_SCOPE__ .search-bar input:focus,
.__UIV_SCOPE__ .search-bar input:valid {
  width: 100%;
}

.__UIV_SCOPE__ .search-bar input:focus,
.__UIV_SCOPE__ .search-bar input:not(:focus) + .search-btn:focus {
  outline: transparent;
}

.__UIV_SCOPE__ .search-bar {
  margin: auto;
  padding: 1.5em;
  justify-content: center;
  max-width: 30em;
}

.__UIV_SCOPE__ .search-bar input {
  background: transparent;
  border-radius: 1.5em;
  box-shadow: 0 0 0 0.4em #171717 inset;
  padding: 0.75em;
  transform: translate(0.5em,0.5em) scale(0.5);
  transform-origin: 100% 0;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

.__UIV_SCOPE__ .search-bar input::-webkit-search-decoration {
  -webkit-appearance: none;
}

.__UIV_SCOPE__ .search-bar input:focus,
.__UIV_SCOPE__ .search-bar input:valid {
  background: #fff;
  border-radius: 0.375em 0 0 0.375em;
  box-shadow: 0 0 0 0.1em #d9d9d9 inset;
  transform: scale(1);
}

.__UIV_SCOPE__ .search-btn {
  background: #171717;
  border-radius: 0 0.75em 0.75em 0 / 0 1.5em 1.5em 0;
  padding: 0.75em;
  position: relative;
  transform: translate(0.25em,0.25em) rotate(45deg) scale(0.25,0.125);
  transform-origin: 0 50%;
}

.__UIV_SCOPE__ .search-btn:before, 
.__UIV_SCOPE__ .search-btn:after {
  content: "";
  display: block;
  opacity: 0;
  position: absolute;
}

.__UIV_SCOPE__ .search-btn:before {
  border-radius: 50%;
  box-shadow: 0 0 0 0.2em #f1f1f1 inset;
  top: 0.75em;
  left: 0.75em;
  width: 1.2em;
  height: 1.2em;
}

.__UIV_SCOPE__ .search-btn:after {
  background: #f1f1f1;
  border-radius: 0 0.25em 0.25em 0;
  top: 51%;
  left: 51%;
  width: 0.75em;
  height: 0.25em;
  transform: translate(0.2em,0) rotate(45deg);
  transform-origin: 0 50%;
}

.__UIV_SCOPE__ .search-btn span {
  display: inline-block;
  overflow: hidden;
  width: 1px;
  height: 1px;
}

/* Active state */
.__UIV_SCOPE__ .search-bar input:focus + .search-btn,
.__UIV_SCOPE__ .search-bar input:valid + .search-btn {
  background: #2762f3;
  border-radius: 0 0.375em 0.375em 0;
  transform: scale(1);
}

.__UIV_SCOPE__ .search-bar input:focus + .search-btn:before, 
.__UIV_SCOPE__ .search-bar input:focus + .search-btn:after, 
.__UIV_SCOPE__ .search-bar input:valid + .search-btn:before, 
.__UIV_SCOPE__ .search-bar input:valid + .search-btn:after {
  opacity: 1;
}

.__UIV_SCOPE__ .search-bar input:focus + .search-btn:hover,
.__UIV_SCOPE__ .search-bar input:valid + .search-btn:hover,
.__UIV_SCOPE__ .search-bar input:valid:not(:focus) + .search-btn:focus {
  background: #0c48db;
}

.__UIV_SCOPE__ .search-bar input:focus + .search-btn:active,
.__UIV_SCOPE__ .search-bar input:valid + .search-btn:active {
  transform: translateY(1px);
}

@media screen and (prefers-color-scheme: dark) {
  .__UIV_SCOPE__, .__UIV_SCOPE__ input {
    color: #f1f1f1;
  }

  .__UIV_SCOPE__ .search-bar input {
    box-shadow: 0 0 0 0.4em #f1f1f1 inset;
  }

  .__UIV_SCOPE__ .search-bar input:focus,
	.__UIV_SCOPE__ .search-bar input:valid {
    background: #3d3d3d;
    box-shadow: 0 0 0 0.1em #3d3d3d inset;
  }

  .__UIV_SCOPE__ .search-btn {
    background: #f1f1f1;
  }
}
